// OpenSRM Timetable Editor — drag-and-drop with mobile touch support
(function() {
    'use strict';

    // audit R1: dead session 302s API routes to /login; fetch() follows it
    // and r.json() throws on the HTML — the tab went silently blank. Same
    // guard dash.js already uses.
    function ttJson(r) {
        if (r.redirected) { location.href = '/login'; return new Promise(function() {}); }
        return r.json();
    }

    function esc(s) { var d = document.createElement('div'); d.appendChild(document.createTextNode(s)); return d.innerHTML; }

    var SLOTS = [
        {period:1, start:'09:30', end:'10:20', type:'class'},
        {period:2, start:'10:20', end:'11:10', type:'class'},
        {period:0, start:'11:10', end:'11:20', type:'break', name:'Break'},
        {period:3, start:'11:20', end:'12:10', type:'class'},
        {period:4, start:'12:10', end:'13:00', type:'class'},
        {period:0, start:'13:00', end:'14:10', type:'break', name:'Lunch'},
        {period:5, start:'14:10', end:'15:00', type:'class'},
        {period:6, start:'15:00', end:'15:50', type:'class'},
        {period:0, start:'15:50', end:'16:00', type:'break', name:'Break'},
        {period:7, start:'16:00', end:'16:50', type:'class'}
    ];
    var DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday'];

    var editorState = {};  // 'day-period': {code, name}
    var subjects = [];
    var groupKey = null;

    function init() {
        var btn = document.getElementById('tt-edit-btn');
        if (btn) btn.addEventListener('click', openEditor);

        var saveBtn = document.getElementById('tt-save-btn');
        if (saveBtn) saveBtn.addEventListener('click', saveTimetable);

        var cancelBtn = document.getElementById('tt-cancel-btn');
        if (cancelBtn) cancelBtn.addEventListener('click', closeEditor);

        var addBtn = document.getElementById('tt-add-subject-btn');
        if (addBtn) addBtn.addEventListener('click', showAddSubject);

        loadHistory();
    }

    // ── Edit history (audit log) ──────────────────────────────────
    // Every value here can be student-controlled (custom subjects, peer
    // edits) — build DOM with textContent ONLY, never innerHTML.
    function loadHistory() {
        var list = document.getElementById('tt-history-list');
        if (!list) return;
        fetch('/api/timetable/history', {credentials: 'same-origin'})
            .then(ttJson)
            .then(function(data) {
                var entries = (data && data.ok && data.entries) || [];
                document.getElementById('tt-history-count').textContent = entries.length;
                list.textContent = '';
                if (!entries.length) {
                    var none = document.createElement('p');
                    none.className = 'text-base-content/60';
                    none.textContent = 'No edits recorded yet.';
                    list.appendChild(none);
                    return;
                }
                entries.forEach(function(e) {
                    var item = document.createElement('div');
                    item.className = 'py-2 border-b border-base-300 last:border-b-0';
                    // one compact head: Name netid ····· rel time (title = absolute)
                    var head = document.createElement('div');
                    head.className = 'flex justify-between items-baseline gap-2';
                    var who = document.createElement('span');
                    who.className = 'text-sm font-medium';
                    who.textContent = e.name || e.netid;
                    if (e.name) {
                        var idEl = document.createElement('span');
                        idEl.className = 'font-mono text-xs text-base-content/60 ml-1';
                        idEl.textContent = e.netid;
                        who.appendChild(idEl);
                    }
                    var when = document.createElement('span');
                    when.className = 'text-xs text-base-content/60 shrink-0';
                    when.textContent = relTime(e.at);
                    when.title = new Date(e.at * 1000).toLocaleString();
                    head.appendChild(who);
                    head.appendChild(when);
                    item.appendChild(head);
                    // changes as terse symbol lines; full subject names in title=
                    var box = document.createElement('div');
                    box.className = 'text-xs text-base-content/60 mt-0.5 space-y-0.5';
                    var chs = e.changes || [];
                    chs.forEach(function(ch, i) {
                        var line = document.createElement('div');
                        line.textContent = chLine(ch);
                        line.title = chFull(ch);
                        if (i >= 3) line.className = 'tt-h hidden';  // bulk saves stay terse
                        box.appendChild(line);
                    });
                    if (chs.length > 3) {
                        var tog = document.createElement('div');
                        tog.className = 'cursor-pointer';
                        tog.title = 'show all changes';
                        var rest = chs.length - 3;
                        tog.textContent = '+' + rest + ' more';
                        tog.onclick = function() {
                            var hid = box.querySelectorAll('.tt-h');
                            var wasCollapsed = hid[0].classList.contains('hidden');
                            for (var k = 0; k < hid.length; k++) hid[k].classList.toggle('hidden', !wasCollapsed);
                            tog.textContent = wasCollapsed ? 'show less' : '+' + rest + ' more';
                        };
                        box.appendChild(tog);
                    }
                    item.appendChild(box);
                    list.appendChild(item);
                });
            })
            .catch(function() {
                list.textContent = '';
                var p = document.createElement('p');
                p.className = 'text-base-content/60';
                p.textContent = 'Could not load edit history.';
                list.appendChild(p);
            });
    }

    var DAY_ABBR = {Monday: 'Mon', Tuesday: 'Tue', Wednesday: 'Wed',
                    Thursday: 'Thu', Friday: 'Fri'};
    function chLine(ch) {
        var where = (DAY_ABBR[ch.day] || ch.day || '') + ' P' + (ch.period || '');
        var code = function(s) { return s ? (s.code || '?') : ''; };
        if (ch.action === 'added')   return where + ': +' + code(ch.to);
        if (ch.action === 'removed') return where + ': -' + code(ch.from);
        return where + ': ' + code(ch.from) + ' → ' + code(ch.to);
    }
    function chFull(ch) {
        var lab = function(s) { return s ? ((s.code || '') + (s.name ? ' ' + s.name : '')) : 'empty'; };
        var where = (ch.day || '') + ' P' + (ch.period || '');
        if (ch.action === 'added')   return where + ' · added ' + lab(ch.to);
        if (ch.action === 'removed') return where + ' · removed ' + lab(ch.from);
        return where + ' · changed ' + lab(ch.from) + ' → ' + lab(ch.to);
    }
    function relTime(ts) {
        var s = Math.floor(Date.now() / 1000) - ts;
        if (s < 60)     return 'ago';
        if (s < 3600)   return Math.floor(s / 60) + 'm ago';
        if (s < 86400)  return Math.floor(s / 3600) + 'h ago';
        if (s < 604800) return Math.floor(s / 86400) + 'd ago';
        return new Date(ts * 1000).toLocaleDateString([], {day: '2-digit', month: 'short'});
    }

    function openEditor() {
        document.getElementById('tab-timetable-view').style.display = 'none';
        document.getElementById('tt-edit-btn').style.display = 'none';
        document.getElementById('tt-editor').style.display = 'block';
        // Reveal the editor action buttons (hidden by default in the template)
        ['tt-save-btn', 'tt-cancel-btn', 'tt-add-subject-btn'].forEach(function(id) {
            document.getElementById(id).classList.remove('hidden');
        });

        // Load current timetable
        fetch('/api/timetable', {credentials: 'same-origin'})
            .then(ttJson)
            .then(function(data) {
                if (!data.ok) return;
                groupKey = data.group_key;
                subjects = data.subjects || [];
                editorState = {};

                // Convert slots to editor state
                var slots = data.slots || {};
                for (var key in slots) {
                    if (slots[key] && slots[key].code) {
                        editorState[key] = slots[key];
                    }
                }

                renderPalette();
                renderGrid();
            });
    }

    function closeEditor() {
        document.getElementById('tab-timetable-view').style.display = '';
        document.getElementById('tt-edit-btn').style.display = '';
        document.getElementById('tt-editor').style.display = 'none';
        ['tt-save-btn', 'tt-cancel-btn', 'tt-add-subject-btn'].forEach(function(id) {
            document.getElementById(id).classList.add('hidden');
        });
    }

    function renderPalette() {
        var el = document.getElementById('tt-palette');
        el.innerHTML = '';
        subjects.forEach(function(s) {
            var block = document.createElement('div');
            block.className = 'tt-subject-block';
            block.draggable = true;
            block.dataset.code = s.code;
            block.dataset.name = s.name;
            block.innerHTML = '<span class="tt-subject-code">' + esc(s.code) + '</span>' +
                              '<span class="tt-subject-name">' + esc(s.name) + '</span>';

            block.addEventListener('dragstart', function(e) {
                e.dataTransfer.setData('text/plain', JSON.stringify({code: s.code, name: s.name}));
                e.dataTransfer.effectAllowed = 'copy';
                block.classList.add('dragging');
            });
            block.addEventListener('dragend', function() {
                block.classList.remove('dragging');
            });

            el.appendChild(block);
        });
    }

    function renderGrid() {
        var grid = document.getElementById('tt-grid-body');
        grid.innerHTML = '';

        var classSlots = SLOTS.filter(function(s) { return s.type === 'class'; });

        // Header row: empty corner + time-slot labels (horizontal = time)
        var header = document.createElement('div');
        header.className = 'tt-grid-header';
        var corner = document.createElement('div');
        header.appendChild(corner);
        classSlots.forEach(function(slot) {
            var h = document.createElement('div');
            h.textContent = slot.start;
            h.title = slot.start + ' - ' + slot.end;
            h.className = 'tt-grid-time';
            header.appendChild(h);
        });
        grid.appendChild(header);

        // Vertical = days of week
        DAYS.forEach(function(day) {
            var row = document.createElement('div');
            row.className = 'tt-grid-row';

            var dayDiv = document.createElement('div');
            dayDiv.className = 'tt-grid-day';
            dayDiv.textContent = day.slice(0, 3);
            row.appendChild(dayDiv);

            classSlots.forEach(function(slot) {
                var cell = document.createElement('div');
                cell.className = 'tt-grid-cell';
                cell.dataset.day = day;
                cell.dataset.period = slot.period;

                var key = day + '-' + slot.period;
                var placed = editorState[key];
                if (placed) {
                    cell.classList.add('tt-cell-filled');
                    cell.innerHTML = '<span class="cell-code">' + esc(placed.code) + '</span>' +
                                     '<button class="cell-remove" data-key="' + key + '">&times;</button>';
                    cell.querySelector('.cell-remove').addEventListener('click', function() {
                        delete editorState[key];
                        renderGrid();
                    });
                }

                // Drop target
                cell.addEventListener('dragover', function(e) {
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'copy';
                    cell.classList.add('tt-cell-hover');
                });
                cell.addEventListener('dragleave', function() {
                    cell.classList.remove('tt-cell-hover');
                });
                cell.addEventListener('drop', function(e) {
                    e.preventDefault();
                    cell.classList.remove('tt-cell-hover');
                    var data = JSON.parse(e.dataTransfer.getData('text/plain'));
                    editorState[key] = {code: data.code, name: data.name};
                    renderGrid();
                });

                row.appendChild(cell);
            });

            grid.appendChild(row);
        });
    }

    function showAddSubject() {
        var modal = document.getElementById('add-subject-modal');
        var codeInput = document.getElementById('subj-code');
        var nameInput = document.getElementById('subj-name');
        var confirmBtn = document.getElementById('subj-confirm-btn');
        codeInput.value = '';
        nameInput.value = '';
        modal.showModal();
        codeInput.focus();

        function onConfirm() {
            var code = codeInput.value.trim().toUpperCase();
            var name = nameInput.value.trim();
            if (!code || !name) return;
            var existing = subjects.find(function(s) { return s.code === code; });
            if (existing) {
                existing.name = name;
            } else {
                subjects.push({code: code, name: name, credits: 0, custom: true});
            }
            renderPalette();
            modal.close();
        }
        function onClose() {
            confirmBtn.removeEventListener('click', onConfirm);
            modal.removeEventListener('close', onClose);
        }
        confirmBtn.addEventListener('click', onConfirm);
        modal.addEventListener('close', onClose);
    }

    function saveTimetable() {
        if (!groupKey) {
            showError('No timetable group found. Login again to create one.');
            return;
        }

        var customSubjects = subjects.filter(function(s) { return s.custom; });

        fetch('/api/timetable', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            credentials: 'same-origin',
            body: JSON.stringify({slots: editorState, custom_subjects: customSubjects})
        })
        .then(ttJson)
        .then(function(data) {
            if (data.ok) {
                closeEditor();
                // archived editor: same contract as the main refresh — update in
                // place, reload only as the fallback if softRefresh is unavailable
                if (typeof softRefresh === 'function') { softRefresh(); } else { location.reload(); }
            } else {
                showError('Save failed: ' + (data.error || 'unknown error'));
            }
        })
        .catch(function(err) {
            showError('Save failed: ' + err.message);
        });
    }

    // Initialize when DOM ready
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();

// audit R1: drag-drop-touch.js shipped but polyfill() was never called —
// touch drag was dead on mobile. No-op on desktop (native DnD detected
// inside polyfill()); the route templates load the lib before this file.
if (window.MobileDragDrop) MobileDragDrop.polyfill();
